"""The hosts file and the names of the dev loop.

``workpeg ui serve --fake-cloud`` makes a project reachable at
``https://<namespace>.dev.workpeg.com`` on this computer, so the page
reaches the API on the same domain a released peg does. This module maps
that name to ``127.0.0.1`` in the hosts file (unix-likes: ``/etc/hosts``,
appended with sudo when not writable directly; Windows:
``%SystemRoot%\\System32\\drivers\\etc\\hosts``, which needs an
Administrator terminal), and ``workpeg ui dev-clean`` takes the lines and
certificates back. :mod:`workpeg.ui.devserve` makes the certificate, with
mkcert alone.

Why not Let's Encrypt: public CAs validate domain control through public
DNS (HTTP-01 / DNS-01 challenges). A hosts-file domain exists only on this
machine, so no public CA can ever issue for it. mkcert gives the same
browser experience — a trusted certificate and a green lock — by creating
a local CA and installing it in the system trust store.
"""

from __future__ import annotations

import os
import platform
import re
import shutil
import subprocess
import tempfile
from pathlib import Path

_HOSTS_MARKER = "# workpeg-fake-cloud"
_CERT_ROOT = Path.home() / ".workpeg" / "fake-cloud"


class FakeCloudError(Exception):
    pass


def slugify(name: str) -> str:
    """Normalize a project name to a domain/namespace slug.

    ``counter`` → ``counter``; ``My App`` → ``my-app``. Returns ``""`` when
    nothing usable remains. This is the slug that becomes the Peg's namespace
    and the leading label of ``<slug>.dev.workpeg.com``, so the two always agree.
    """
    slug = re.sub(r"[\s_]+", "-", name.strip().lower())
    return re.sub(r"[^a-z0-9-]", "", slug).strip("-")


# A plain hostname: dot-separated LDH labels, ≤253 chars. Anything else — a
# space, newline, slash, shell metachar — is rejected before it reaches a hosts
# file (where a newline could inject another mapping), a cert subject, or a path.
_VALID_DOMAIN = re.compile(
    r"^(?=.{1,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?"
    r"(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$",
    re.IGNORECASE,
)


def _require_valid_domain(domain: str) -> None:
    if not isinstance(domain, str) or not _VALID_DOMAIN.match(domain):
        raise FakeCloudError(f"Refusing to use an invalid hostname: {domain!r}")


def _lock_down_key(key: "Path") -> None:
    """Make a generated TLS private key owner read/write only (0600). A no-op
    where POSIX permissions don't apply."""
    try:
        os.chmod(key, 0o600)
    except OSError:
        pass


def derive_app_name(source: str) -> str:
    """Project name for a serve source — a project dir, dist dir, or .py file."""
    p = Path(source).resolve()
    if p.suffix == ".py":
        p = p.parent
    if p.name == "dist":
        p = p.parent
    return p.name


def hosts_path_for_os() -> str:
    """Return the hosts file path for this OS.

    Windows keeps it under ``%SystemRoot%\\System32\\drivers\\etc``;
    macOS, Linux, and other unix-likes use ``/etc/hosts``.
    """
    if platform.system() == "Windows":
        windir = os.environ.get("SystemRoot", r"C:\Windows")
        return os.path.join(windir, "System32", "drivers", "etc", "hosts")
    return "/etc/hosts"


#: The one address a dev page's name is mapped to.
LOOPBACK = "127.0.0.1"


def _mapped_addresses(content: str, domain: str) -> "set[str]":
    """Return the addresses *domain* is already mapped to in *content*."""
    found = set()
    for line in content.splitlines():
        fields = line.split("#")[0].split()
        if len(fields) >= 2 and domain in fields[1:]:
            found.add(fields[0])
    return found


def _append_to_file(path: str, text: str) -> None:
    """Append *text* to *path* — separated out so tests can simulate
    permission failures without touching real system files."""
    with open(path, "a") as f:
        f.write(text)


def _overwrite_file(path: str, text: str) -> None:
    """Replace the contents of *path* — separated out for the same reason as
    ``_append_to_file``."""
    with open(path, "w") as f:
        f.write(text)


def _strip_hosts_entries(
    content: str, domain: str, keep: "tuple[str, ...]" = ()
) -> "tuple[str, bool]":
    """Drop the hosts lines mapping *domain*, returning ``(content, removed)``.

    Only lines carrying ``_HOSTS_MARKER`` are eligible. That restriction is the
    whole safety argument for removal: this rewrites /etc/hosts, so it must
    touch nothing but the lines this tool wrote itself. A developer who typed
    the same mapping by hand keeps it. A marked line for an address in *keep*
    stays too.
    """
    kept: list[str] = []
    removed = False
    for line in content.splitlines(keepends=True):
        fields = line.split("#")[0].split()
        if (_HOSTS_MARKER in line and len(fields) >= 2
                and domain in fields[1:] and fields[0] not in keep):
            removed = True
            continue
        kept.append(line)
    return "".join(kept), removed


def remove_hosts_entry(
    domain: str, hosts_path: "str | None" = None,
    keep: "tuple[str, ...]" = (),
) -> bool:
    """Remove our own mappings for *domain*, but for any address in *keep*.
    True when one went away.

    Unlike ``ensure_hosts_entry`` this cannot append — it has to rewrite the
    whole file — so it writes nothing at all unless there is something to
    remove. What makes the rewrite safe is the marker check in
    ``_strip_hosts_entries``, not the size of the result: a hosts file that
    contains only our line is a legitimate thing to empty (minimal containers
    have one), so there is no threshold worth refusing on.

    The write is in-place rather than a write-temp-and-rename, deliberately.
    Renaming would install a file owned by whoever ran the CLI, with that
    process's umask, over a root-owned 0644 /etc/hosts — locking every other
    user on the machine out of name resolution. Truncate-and-write keeps the
    original ownership and mode.
    """
    _require_valid_domain(domain)
    path = hosts_path or hosts_path_for_os()
    content = Path(path).read_text()
    new_content, removed = _strip_hosts_entries(content, domain, keep)
    if not removed:
        return False                       # never rewrite for nothing

    try:
        _overwrite_file(path, new_content)
    except PermissionError:
        if platform.system() == "Windows":
            raise FakeCloudError(
                f"Cannot write {path}. Re-run from an Administrator "
                f"terminal, or delete the line mapping {domain} by hand."
            )
        print(f"  Removing the stale {domain} from {path} (requires sudo)...")

        # Authenticate BEFORE re-reading, because `sudo tee` is handed its
        # whole stdin up front: the content is fixed before the password
        # prompt, so the snapshot taken above would be as stale as the
        # developer is slow to type. The append path has no such window — it
        # appends whatever the file has become — but a rewrite replaces lines
        # it never saw, so a dev page started in another terminal that added
        # its entry mid-prompt would lose it. `sudo -v` moves the prompt out
        # of the window; its exit status is ignored on purpose, because the
        # tee below is the authority on whether we may write at all (a
        # NOPASSWD or already-cached sudoer makes this a silent no-op).
        subprocess.run(["sudo", "-v"])
        new_content, removed = _strip_hosts_entries(
            Path(path).read_text(), domain, keep)
        if not removed:
            return False               # someone else got there during the prompt

        # `sudo tee` without -a, i.e. truncate-and-write. Same no-shell-string
        # argument as the append path; the content is passed on stdin.
        result = subprocess.run(
            ["sudo", "tee", path],
            input=new_content,
            text=True,
            stdout=subprocess.DEVNULL,
        )
        if result.returncode != 0:
            raise FakeCloudError(
                f"Could not remove {domain} from {path}. Delete the line "
                f"tagged '{_HOSTS_MARKER}' by hand."
            )
    return True


def ensure_hosts_entry(domain: str, hosts_path: "str | None" = None) -> bool:
    """Map *domain* to ``127.0.0.1``, and nothing else, in the hosts file.

    IPv4 alone, so no other program on this computer listening on
    ``[::1]:443`` is handed the session a dev page holds.

    Returns True when an entry was added, False when one already existed.
    Tries a direct append first. When the file is not writable, unix-likes
    fall back to a sudo prompt (the normal case on macOS); Windows has no
    sudo equivalent, so the command must be re-run from an Administrator
    terminal. Entries are tagged with a marker comment so they are easy
    to find and remove later (``workpeg ui dev-clean``).
    """
    _require_valid_domain(domain)
    path = hosts_path or hosts_path_for_os()
    content = Path(path).read_text()
    if LOOPBACK in _mapped_addresses(content, domain):
        return False

    entry = f"{LOOPBACK} {domain} {_HOSTS_MARKER}\n"
    prefix = "" if content.endswith("\n") or not content else "\n"
    try:
        _append_to_file(path, prefix + entry)
    except PermissionError:
        if platform.system() == "Windows":
            raise FakeCloudError(
                f"Cannot write {path}. Re-run from an Administrator "
                f"terminal, or add this line manually:\n"
                f"  {LOOPBACK} {domain}"
            )
        print(f"  Adding {domain} to {path} (requires sudo)...")
        # Append via `sudo tee -a`, feeding the line on stdin — no shell string
        # is built, so nothing in *domain*/*path* is ever interpreted by a shell
        # (this runs under sudo). `tee` prints what it writes; swallow it.
        result = subprocess.run(
            ["sudo", "tee", "-a", path],
            input=prefix + entry,
            text=True,
            stdout=subprocess.DEVNULL,
        )
        if result.returncode != 0 and _can_ask_graphically():
            # `sudo` needs a terminal to prompt in, and there is not always one —
            # an editor's task runner, a background start. Without a terminal it
            # fails instantly with "a password is required" and the developer is
            # told to edit /etc/hosts by hand, which is the one thing this was
            # meant to spare them.
            #
            # macOS can ask without one. The dialog is the operating system's, names
            # what it will do, and the password never reaches this process.
            result = _ask_graphically(path, prefix + entry)
        if result.returncode != 0:
            raise FakeCloudError(
                f"Could not add {domain} to {path}. Add this line "
                f"by hand:\n  {LOOPBACK} {domain}"
            )
    return True


def _can_ask_graphically() -> bool:
    """Return whether this machine can prompt for a password without a terminal."""
    return platform.system() == "Darwin" and shutil.which("osascript") is not None


def _ask_graphically(path: str, text: str):
    """Append *text* to *path* as root, prompting through the OS dialog.

    Used only when `sudo` had no terminal to ask in. The password is typed into the
    operating system's own dialog and never passes through this process.

    **The line is staged in a file, not piped.** `do shell script` runs its command
    with no stdin, so feeding the text to `osascript` sends it nowhere: `tee` reads
    nothing, writes nothing, and exits 0 — the entry silently does not appear while
    every return code says it did. So the line is written to a temporary file first and
    the elevated command copies from there.

    **Nothing from outside is interpolated into the script.** Both paths are ones this
    process computed, and both are quoted. That matters more here than in the `sudo`
    branch above, because this string really is handed to a shell, as root.
    """
    staged = tempfile.NamedTemporaryFile(
        "w", suffix=".hosts", delete=False, encoding="utf-8",
    )
    try:
        staged.write(text)
        staged.close()
        script = (
            f"do shell script \"cat {_quote(staged.name)} >> {_quote(path)}\" "
            f"with administrator privileges"
        )
        return subprocess.run(
            ["osascript", "-e", script],
            text=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    finally:
        try:
            os.unlink(staged.name)
        except OSError:
            pass


def _quote(value: str) -> str:
    """Return *value* as a single-quoted shell word."""
    return "'" + str(value).replace("'", "'\\''") + "'"


# ------------------------------------------------------------- dev-clean

#: What ``workpeg ui dev-clean`` says every time, because it is the one thing
#: the dev loop installs that the command does not take back. mkcert's root
#: CA is shared by every certificate mkcert ever made on this computer, for
#: any tool, so removing it is the developer's call, not this command's.
MKCERT_STAYS = (
    "mkcert's root CA stays in this computer's trust store, so what it "
    "signed is still trusted. `mkcert -uninstall` removes it."
)


def escaped(text: object) -> str:
    """*text* with every unprintable character written as an escape, so a
    name read from a hosts file or a folder cannot drive the terminal (move
    the cursor, retitle the window, hide a line)."""
    return "".join(
        c if c.isprintable() else ascii(c)[1:-1] for c in str(text))


def project_domains(project: str) -> "list[str]":
    """Every name the dev loop may have mapped for *project*, in order.

    Each of the project's two names: the namespace the build uses
    (``workpeg.json`` first, then the folder), which is what a dev page is
    served at, ``<namespace>.dev.workpeg.com``, and the folder alone, which
    is what an older ``--fake-cloud`` derived; each as
    ``<slug>.dev.workpeg.com`` and as the older ``dev.<slug>.workpeg.com``.
    The folder need not exist any more: cleaning up after a project is
    exactly when it may be gone. An empty slug gives no valid host, and
    ``dev_clean`` skips any name that is not one.
    """
    from workpeg.ui.build import _peg_namespace

    path = Path(project)
    if path.suffix == ".py":
        entry = path
    elif path.name == "dist":
        entry = path.parent / "main.py"
    else:
        entry = path / "main.py"
    slugs = [_peg_namespace(str(entry)), slugify(derive_app_name(project))]
    names: "list[str]" = []
    for slug in slugs:
        for name in (f"{slug}.dev.workpeg.com", f"dev.{slug}.workpeg.com"):
            if name not in names:
                names.append(name)
    return names


def marked_names(content: str) -> "list[str]":
    """The names on every line carrying the marker, once each, in file order.
    A commented-out line maps nothing, so it names nothing."""
    names: "list[str]" = []
    for line in content.splitlines():
        if _HOSTS_MARKER not in line:
            continue
        for name in line.split("#")[0].split()[1:]:
            if name not in names:
                names.append(name)
    return names


def _remove_cert_folder(folder: Path) -> bool:
    """Delete one certificate folder. A link in its place is unlinked and
    never followed, so what it points at is untouched."""
    if os.path.islink(folder):
        os.unlink(folder)
        return True
    if folder.is_dir():
        shutil.rmtree(folder)
        return True
    return False


def dev_clean(
    domains: "list[str] | None",
    hosts_path: "str | None" = None,
    cert_root: "Path | str | None" = None,
) -> "tuple[list[tuple[str, list[str]]], list[str]]":
    """Take back the marked hosts lines and the certificate folders for
    *domains*, or for every marked name and every certificate folder when
    *domains* is None. Returns ``(removed, left)``: each removed domain once
    with what went (``"hosts lines"``, ``"certificate"``), and the marked
    names left in place.

    The hosts file is rewritten only by ``remove_hosts_entry``, so the
    marker check, the in-place write that keeps the file's owner and mode,
    the sudo fallback and the re-read after the password prompt are the
    ones the dev page's server relies on when it takes out an old line. A marked line
    whose name is not a valid host is LEFT: ``ensure_hosts_entry`` refuses
    such a name, so the SDK never wrote it and somebody edited the line by
    hand.

    Reads no credential and opens no connection.
    """
    path = hosts_path or hosts_path_for_os()
    # Read at call time, not from _CERT_ROOT, so it follows the HOME the
    # command runs under.
    root = Path(cert_root) if cert_root else (
        Path.home() / ".workpeg" / "fake-cloud")
    try:
        marked = marked_names(Path(path).read_text())
    except FileNotFoundError:
        marked = []

    if domains is None:
        targets = list(marked)
        if root.is_dir():
            targets += sorted(
                child.name for child in root.iterdir()
                if child.name not in targets)
    else:
        targets = list(domains)

    left = [d for d in targets if d in marked and not _VALID_DOMAIN.match(d)]
    targets = [d for d in targets if _VALID_DOMAIN.match(d)]
    removed: "list[tuple[str, list[str]]]" = []
    for domain in targets:
        what = []
        # Marked, so removed: remove_hosts_entry raises when it cannot write,
        # and answers False only when the line is already gone (another
        # name on the same line took it, or another run did).
        if domain in marked:
            remove_hosts_entry(domain, path)
            what.append("hosts lines")
        if _remove_cert_folder(root / domain):
            what.append("certificate")
        if what:
            removed.append((domain, what))
    return removed, left
